"""Figures for NotesCLAUDE/circle_fidelity_MIRROR.md. Generated by Claude Opus 5.5 -- 01/10/2026."""
import json, os
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker
HERE = os.path.dirname(os.path.abspath(__file__))
res = json.load(open(os.path.join(HERE, 'OutCLAUDE', 'sweep_MIRROR.json')))
LAT = ['sq5', 'sq9', 'tri']
COL = {'sq5': '#2a78d6', 'sq9': '#eb6834', 'tri': '#1baf7a'}
MK = {'sq5': 'o', 'sq9': 's', 'tri': '^'}
SG = {'3': 'sigma = 3 cells (fixed)', 'f0.025': 'sigma = R/40 (fixed fraction)'}
plt.rcParams.update({'font.size': 9, 'axes.spines.top': False, 'axes.spines.right': False,
                     'axes.grid': True, 'grid.color': '#dddddd', 'grid.linewidth': 0.6})
def get(lat, N, co, sg):
    for r in res:
        if (r['lattice'], r['N'], r['co_tag'], r['sig_tag']) == (lat, N, co, sg):
            return r
Ns = sorted({r['N'] for r in res})
NREF = Ns[-1]                              # 02/10/2026: largest N (2049) now that the sweep is complete
save = lambda fig, n: (fig.savefig(os.path.join(HERE, n), dpi=150, bbox_inches='tight'), plt.close(fig))

# 1: eps_ang vs time
fig, ax = plt.subplots(1, 2, figsize=(10, 3.6), sharey=True)
for a, sg in zip(ax, SG):
    for lat in LAT:
        r = get(lat, NREF, '0.5', sg)
        tt, e = np.array(r['trip'][1:]), np.array(r['eps_ang'][1:])
        a.semilogy(tt, e, color=COL[lat], lw=2, marker=MK[lat], ms=4, label=lat)
    a.axhline(r['eps_ang'][0], color='#888888', lw=1, ls=':')
    a.text(0.2, r['eps_ang'][0] * 1.6, 'metric floor', color='#666666', fontsize=8)
    a.set_title(f'N = {NREF}, Co = 0.5, {SG[sg]}')
    a.set_xlabel('time / round trip (2R/c)')
ax[0].set_ylabel('energy fraction in angular modes m != 0')
ax[0].legend(frameon=False)
save(fig, 'fig1_eps_ang_time_MIRROR.png')

# 2: scaling with N
fig, ax = plt.subplots(1, 2, figsize=(10, 3.6), sharey=True)
for a, sg in zip(ax, SG):
    for lat in LAT:
        for k, ls in [(1, '--'), (10, '-')]:
            v = [get(lat, N, '0.5', sg)['eps_ang'][4 * k] for N in Ns]
            a.loglog(Ns, v, color=COL[lat], lw=2, ls=ls, marker=MK[lat], ms=5,
                     label=f'{lat}, trip {k}')
    a.set_title(f'Co = 0.5, {SG[sg]}')
    a.set_xlabel('N (grid size; R = 0.433 N)')
    a.set_xticks(Ns); a.set_xticklabels(map(str, Ns)); a.xaxis.set_minor_formatter(matplotlib.ticker.NullFormatter())
ax[0].set_ylabel('energy fraction in m != 0')
ax[1].legend(frameon=False, fontsize=7, ncol=3)
save(fig, 'fig2_eps_ang_vs_N_MIRROR.png')

# 3: angular spectrum at trip 10
fig, ax = plt.subplots(1, 3, figsize=(11, 3.2), sharey=True)
for a, lat in zip(ax, LAT):
    r = get(lat, NREF, '0.5', 'f0.025')
    Em = np.array(r['Em'][-1]); Em = Em / r['E_tot'][-1]
    m = np.arange(1, Em.size)
    a.bar(m, Em[1:], color=COL[lat], width=0.8)
    for k in (4, 6, 8, 12):
        pass
    a.set_yscale('log'); a.set_ylim(1e-9, 1e-1)
    a.set_title(f'{lat}: N {NREF}, sigma R/40, trip 10', fontsize=8)
    a.set_xlabel('angular mode m'); a.set_xticks([4, 8, 12, 16, 24, 32, 48, 64])
ax[0].set_ylabel('E_m / E_total')
save(fig, 'fig3_angular_spectrum_MIRROR.png')

# 4: eps_0 (m = 0 vs Bessel reference) by Co
fig, ax = plt.subplots(1, 3, figsize=(11, 3.2), sharey=True)
SEQ = {'0.5': '#86b6ef', 'r0.9': '#3987e5', 'r0.99': '#1c5cab'}
for a, lat in zip(ax, LAT):
    for co in ['0.5', 'r0.9', 'r0.99']:
        r = get(lat, NREF, co, 'f0.025')
        a.semilogy(r['trip'][1:], r['eps_0'][1:], color=SEQ[co], lw=2, label=f"Co = {r['Co']:.3f}")
    a.set_title(f'{lat}: m = 0 error, N {NREF}, sigma R/40', fontsize=8)
    a.set_xlabel('time / round trip'); a.legend(frameon=False, fontsize=7)
ax[0].set_ylabel('energy of (m=0 part - exact) / E')
save(fig, 'fig4_eps0_by_Co_MIRROR.png')
# 5: staircase vs bulk anisotropy (added 02/10/2026, Claude Opus 5.5): free-space eps after a 2R path vs trip 1 in the circle
fs = json.load(open(os.path.join(HERE, 'OutCLAUDE', 'freespace_MIRROR.json')))
fig, ax = plt.subplots(1, 2, figsize=(10, 3.4), sharey=True)
for a, (Nn, lab) in zip(ax, [(513, 'N = 513'), (1025, 'N = 1025')]):
    rows = [x for x in fs if x['N_small'] == Nn]
    for i, x in enumerate(rows):
        sgt = '3' if abs(x['sigma'] - 3) < 1e-9 else 'f0.025'
        t1 = get(x['lattice'], Nn, '0.5', sgt)['eps_ang'][4]
        a.bar(i - 0.2, t1, 0.4, color=COL[x['lattice']], alpha=0.45)
        a.bar(i + 0.2, x['eps_free'], 0.4, color=COL[x['lattice']])
    a.set_yscale('log'); a.set_xticks(range(len(rows)))
    a.set_xticklabels([f"{x['lattice']} s{x['sigma']:.1f}" for x in rows], fontsize=7, rotation=30)
    a.set_title(f'{lab}: light = circle trip 1, dark = free space 2R', fontsize=8)
ax[0].set_ylabel('energy fraction in m != 0')
save(fig, 'fig5_staircase_vs_bulk_MIRROR.png')
print('ok')
